	'help.open': 'Bu ekran ne işe yarar?',
	'help.exampleLabel': 'Örnek',

	'help.untouched.title': 'Temassız Kişiler',
	'help.untouched.b1':
		'Uzun süredir kimsenin dokunmadığı kişileri gösterir. "Dokunmak" demek: randevu, ödeme ya da not girilmiş olması.',
	'help.untouched.b2':
		'En uzun süredir unutulmuş olan en üstte. Listeyi yukarıdan aşağı arayarak ilerlersiniz.',
	'help.untouched.example':
		'Ahmet Bey 3 ay önce fiyat sordu, kimse geri dönmedi. Bu listede en üstte çıkar. Bir telefonla tekrar sürece girebilir.',
	'help.untouched.caveat':
		'Yakın tarihte randevusu olan kişiler listede yer almaz — onlar zaten takipte sayılır.',

	'help.incentives.title': 'Teşvik dosyaları',
	'help.incentives.b1':
		'Teşvik başvurusu için sürenin dolmasını engeller. Ödeme tarihini girersiniz, son başvuru gününü sistem hesaplar.',
	'help.incentives.b2':
		'Süresi yaklaşan turuncu, geçmiş kırmızı görünür. Belgeleri tek tek işaretleyebilirsiniz.',
	'help.incentives.example':
		"15 Mart'ta tahsilat yaptınız. Sistem son başvuru gününü yazar ve gün saymaya başlar. 60 gün kalınca satır turuncuya döner.",
	'help.incentives.caveat':
		'Burada oran veya tutar hesaplanmaz, uygunluk kararı verilmez. Yalnız kayıt ve süre tutulur; başvuru ve mevzuat sizin tarafınızdadır.',

	'help.operation-alerts.title': 'Operasyon alarmları',
	'help.operation-alerts.b1':
		'Uçuş, transfer, karşılama ve klinik teyitlerini saate bağlar. Eşik dolunca hâlâ teyitsizse satır alarm verir — kimse “yaptık sanıyordum” diyemez.',
	'help.operation-alerts.b2':
		'Kalan saat eksiye düşünce kırmızı, 6 saatin altına inince turuncu. Teyit düğmesi saati durdurur.',
	'help.operation-alerts.b3':
		'Eşik saatini değiştirmek veya kullanmadığınız bir türü kapatmak için Ayarlar → Operasyon alarmları ekranına gidin.',
	'help.operation-alerts.example':
		'Hastanın uçuşu pazartesi 10:00. Sistem 48 saat önce, cumartesi 10:00’da, teyit yoksa alarm açar. Teyit etmezseniz hasta havaalanında bekler.',
	'help.operation-alerts.caveat':
		'Bu bir kural motorudur, tahmin değildir. Model bir şey yorumlamaz; teyit düğmesine basılmadan kalem kapanmış sayılmaz.',

	'help.operation-alert-settings.title': 'Operasyon alarmı ayarları',
	'help.operation-alert-settings.b1':
		'Her alarm türü için kaç saat önce çalacağını ve o türün açık olup olmadığını buradan belirlersiniz. Kapalı tür yeni randevuda oluşmaz.',
	'help.operation-alert-settings.b2':
		'Kaydetmek dört türü birden yazar. Kısmi kayıt yoktur — kullanmadığınız türü kapatın, eşiği olduğu gibi bırakın.',
	'help.operation-alert-settings.example':
		'Uçuş alarmını 48 yerine 24 saate çekerseniz, teyit edilmemiş uçuş alarmları yeni saate göre kayar; teyit ettikleriniz olduğu gibi kalır.',
	'help.operation-alert-settings.caveat':
		'Kapatılan türün bekleyen (teyitsiz) alarmları listeden düşer. Teyit edilmiş satır bir insan kaydıdır, ayar onu silmez. Türü yeniden açmak geçmiş randevulara alarm üretmez.',

	'help.record-suggestions.title': 'Kayıt güncelleme önerileri',
	'help.record-suggestions.b1':
		'Operasyon mesajlarından randevu tarihi değişikliği önerileri üretir. Sistem okur, siz tek tek onaylarsınız.',
	'help.record-suggestions.b2':
		'Her kart yalnızca bir randevunun başlangıç saatini hedefler. Eşleşme belirsizse öneri hiç oluşmaz.',
	'help.record-suggestions.example':
		'"Ayşe Hanım randevusunu 15 Mayıs 14:00\'a alalım" mesajı gelir → kartta mevcut tarih → önerilen tarih görünür → Onayla\'ya basmadan randevu değişmez.',
	'help.record-suggestions.caveat':
		'Onaylamadan hiçbir şey değişmez. Toplu kabul yoktur; her öneri ayrı karar ister.',

	'help.commissions.title': 'Hakediş / komisyon',
	'help.commissions.b1':
		'Kliniğe, yönlendirene veya alt acenteye olan borcunuzu takip eder. Tutarı siz girersiniz.',
	'help.commissions.b2':
		'Üstteki özet kazanan başına üç şey gösterir: ne kadar hak edildi, ne kadar ödendi, ne kadar kaldı. Ay sonu mutabakatını "kalan" ile yaparsınız.',
	'help.commissions.example':
		'X Kliniği için 10.000 TL hakediş girdiniz, 4.000 TL ödediniz. Özette: hak edilen 10.000, ödenen 4.000, kalan 6.000.',
	'help.commissions.caveat':
		'Komisyon otomatik hesaplanmaz — yüzde formülü yoktur. Kural her klinikte farklı olduğu için tutarı siz yazarsınız.',

	'help.cohorts.title': 'Kohort Görünümü',
	'help.cohorts.b1':
		'Kişi hangi ay geldiyse o aya yazılır. Parası ne zaman gelirse gelsin yine o aya sayılır.',
	'help.cohorts.b2':
		'Sağdaki m0/m1/m2/m3+ sütunları paranın kaçıncı ayda geldiğini gösterir. "Reklam ayı kârsız görünüyor" yanılgısı böyle ortadan kalkar.',
	'help.cohorts.example':
		"Nisan'da gelen hasta parayı Temmuz'da ödedi. Normal raporda para Temmuz'a yazılır ve Nisan boşa gitmiş görünür. Burada Nisan satırında, \"m3+\" sütununda görünür.",
	'help.cohorts.caveat':
		'Harcama sütununda "—" varsa o ay reklam verisi yok demektir; harcama sıfır demek değildir. Ayrıca bir ayki harcamanın o ay gelen kişileri getirdiği varsayılır — kampanya bazlı atıf değildir.',

