	'help.maya.title': 'Maya AI',
	'help.maya.b1':
		'Answers questions from your company knowledge base: services, prices, payment rules, what you do not accept.',
	'help.maya.b2':
		'It never invents anything missing from the knowledge base — it says it does not know and points you where to add it.',
	'help.maya.example':
		'Ask "how much is a hair transplant?" and if your knowledge base says "Hair transplant 2,500 EUR", that is the answer. If not, it says it could not find it rather than guessing.',
	'help.maya.caveat':
		'If your knowledge base is empty, Maya cannot answer anything. Fill in Settings → Knowledge base first.',
	'help.knowledge.title': 'Knowledge base',
	'help.knowledge.b1':
		'Where you write your own company facts: what you sell, for how much, and what you refuse.',
	'help.knowledge.b2':
		'The AI uses this when reading a WhatsApp message. Leave it empty and it has to guess.',
	'help.knowledge.example':
		'If you wrote "Hair transplant 2,500 EUR", a message saying "we agreed on the hair transplant" is read with the right amount. Without it the amount is left blank or guessed wrong.',
	'help.knowledge.caveat':
		'Do not put patient data here (names, phones, IDs) — this is for company information. You will see a warning if you do.',

	'help.open': 'What is this screen for?',
	'help.exampleLabel': 'Example',

	'help.untouched.title': 'Untouched Contacts',
	'help.untouched.b1':
		'Shows contacts nobody has touched for a long time. "Touch" means an appointment, a payment, or a note.',
	'help.untouched.b2': 'The longest-forgotten sits at the top. You work the list top to bottom.',
	'help.untouched.example':
		'Ahmet asked for a price 3 months ago and nobody followed up. He appears at the top of this list. One call can bring him back into the process.',
	'help.untouched.caveat':
		'Contacts with an upcoming appointment are excluded — they already count as handled.',

	'help.incentives.title': 'Incentive files',
	'help.incentives.b1':
		'Keeps the incentive application deadline from slipping. You enter the payment date; the system computes the deadline.',
	'help.incentives.b2':
		'Approaching deadlines turn amber, passed ones red. You can tick documents off one by one.',
	'help.incentives.example':
		'You collected payment on 15 March. The system writes the deadline and starts counting. At 60 days left the row turns amber.',
	'help.incentives.caveat':
		'No rate or amount is calculated here and no eligibility decision is made. Only the record and the deadline are kept; the application and the regulation are on your side.',

	'help.operation-alerts.title': 'Operation alerts',
	'help.operation-alerts.b1':
		'Ties flight, transfer, welcome, and clinic confirmations to a clock. When the threshold hits and the item is still unconfirmed, the row alarms — nobody can say “we thought it was done”.',
	'help.operation-alerts.b2':
		'Negative hours turn red; under 6 hours turns amber. Confirm stops the clock.',
	'help.operation-alerts.b3':
		'To change the threshold hours or turn off a kind you do not use, go to Settings → Operation alerts.',
	'help.operation-alerts.example':
		'The patient’s flight is Monday 10:00. The system alarms 48 hours earlier, Saturday 10:00, if still unconfirmed. Skip confirm and the patient waits at the airport.',
	'help.operation-alerts.caveat':
		'This is a rule engine, not a prediction. No model interprets anything; an item is not closed until someone presses Confirm.',

	'help.operation-alert-settings.title': 'Operation alert settings',
	'help.operation-alert-settings.b1':
		'Set how many hours before the appointment each kind should fire, and whether that kind is on. A disabled kind is not created for new appointments.',
	'help.operation-alert-settings.b2':
		'Saving writes all four kinds. There is no partial save — turn off unused kinds and leave their hours as they are.',
	'help.operation-alert-settings.example':
		'If you pull the flight alert from 48 hours down to 24, unconfirmed flight alerts shift to the new time; the ones you already confirmed stay as they are.',
	'help.operation-alert-settings.caveat':
		'Pending (unconfirmed) alerts of a disabled kind drop off the list. A confirmed row is a human record; settings will not delete it. Turning a kind back on does not create alerts for past appointments.',

	'help.record-suggestions.title': 'Record update suggestions',
	'help.record-suggestions.b1':
		'Produces appointment date change suggestions from operational messages. The system reads; you approve each card individually.',
	'help.record-suggestions.b2':
		'Each card targets one appointment start time only. If the match is ambiguous, no suggestion is created.',
	'help.record-suggestions.example':
		'Message: "Move Ayşe\'s appointment to 15 May 14:00" → card shows current → suggested time → nothing changes until you press Approve.',
	'help.record-suggestions.caveat':
		'Nothing changes without approval. There is no bulk accept; every suggestion needs its own decision.',

	'help.commissions.title': 'Commission',
	'help.commissions.b1':
		'Tracks what you owe a clinic, a referrer, or a sub-agency. You enter the amount.',
	'help.commissions.b2':
		'The summary shows three things per beneficiary: earned, paid, and outstanding. Month-end reconciliation runs on "outstanding".',
	'help.commissions.example':
		'You recorded 10,000 for Clinic X and paid 4,000. The summary reads: earned 10,000, paid 4,000, outstanding 6,000.',
	'help.commissions.caveat':
		'Commission is not calculated automatically — there is no percentage formula. Rules differ per clinic, so you enter the amount.',

	'help.cohorts.title': 'Cohort View',
	'help.cohorts.b1':
		'A contact is filed under the month they arrived. Whenever their money comes in, it still counts to that month.',
	'help.cohorts.b2':
		'The m0/m1/m2/m3+ columns show which month the money landed in. That removes the "the ad month looks unprofitable" illusion.',
	'help.cohorts.example':
		'A patient who arrived in April paid in July. A normal report files the money under July and April looks wasted. Here it shows on the April row, in the "m3+" column.',
	'help.cohorts.caveat':
		'A "—" in the spend column means there is no ad data for that month — not that spend was zero. Also, a month\'s spend is assumed to have brought that month\'s contacts; this is not campaign-level attribution.',

